float hash21(float2 p)
{
    p = frac(p * float2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return frac(p.x * p.y);
}

float vnoise(float2 p)
{
    float2 c = floor(p);
    float2 f = frac(p);
    float2 u = f * f * (3.0 - 2.0 * f);
    float a = hash21(c);
    float b = hash21(c + float2(1.0, 0.0));
    float d = hash21(c + float2(0.0, 1.0));
    float e = hash21(c + float2(1.0, 1.0));
    return lerp(lerp(a, b, u.x), lerp(d, e, u.x), u.y);
}

float fbm(float2 p)
{
    float v = 0.0;
    float a = 0.5;
    for (int k = 0; k < 4; k++) { v += a * vnoise(p); p = p * 2.03 + float2(1.7, 9.2); a *= 0.5; }
    return v;
}

float2 arcRS(float2 uv)
{
    float2 p = uv - 0.5;
    float r = length(p) * 2.0;
    float th = atan2(p.y, p.x) * 57.29578;
    th = th + step(th, -90.0) * 360.0;
    return float2(r, (165.0 - th) / 150.0);
}

float arcProfile(float sc)
{
    return pow(sc, 0.9) * (1.0 - smoothstep(0.86, 1.0, sc));
}

// ince çizgi: merkez c, yarı kalınlık h
float lineAt(float r, float c, float h)
{
    return 1.0 - smoothstep(0.0, max(h, 0.0005), abs(r - c));
}

code.fragment:
float4 frag(UPEInput i)
{
    float life = 1.0 - i.color.a;
    float2 a = arcRS(i.uv);
    float r = a.x;
    float s = a.y;
    float sc = saturate(s);
    float inArc = step(0.0, s) * step(s, 1.0);
    float R0 = 0.94;
    float prof = arcProfile(sc);
    float w = _Width * prof;

    float rev = saturate(life / _Reveal);
    float revealM = 1.0 - smoothstep(rev * 1.04 - 0.05, rev * 1.04, s);
    float e = saturate((life - _ErodeStart) / max(1.0 - _ErodeStart, 0.001));
    float er = fbm(float2(s * 7.0, r * 9.0));
    float erodeM = saturate((er + 0.5 - e * 1.35 - (1.0 - sc) * e * 0.6) * 6.0);
    // başın hemen arkası daha parlak (bıçağın az önce geçtiği yer)
    float headHot = 1.0 + 1.5 * (1.0 - smoothstep(0.0, 0.25, rev * 1.04 - s)) * (1.0 - e);

    float edge = lineAt(r, R0 - _EdgeW * 0.6 * prof, _EdgeW * (0.35 + prof)) * smoothstep(0.0, 0.15, sc);
    float br = step(0.42, vnoise(float2(s * 14.0, 3.0)));
    float br2 = step(0.5, vnoise(float2(s * 9.0, 11.0)));
    float streak = (lineAt(r, R0 - w * 0.38, 0.0035) * br + lineAt(r, R0 - w * 0.72, 0.003) * br2 * 0.7) * _Streaks * step(0.001, w);
    float innerR = R0 - w;
    float d = saturate((r - innerR) / max(w, 0.001));
    float bandM = step(innerR, r) * step(r, R0);
    float glow = bandM * pow(d, 2.5) * _Glow;

    float3 col = _EdgeColor.rgb * edge * headHot + _GlowColor.rgb * (streak + glow);
    float m = inArc * revealM * erodeM;
    col *= i.color.rgb * m;
    return float4(col, 1.0);
}
